        // Create 10 threads, each executing calculate() on a different input
        Thread[] threads = new Thread[10];
        for (int i = 0; i < 10; i++) {
            final int input = i;
            threads[i] = new Thread(() -> calculator.calculate(input));
            threads[i].start();
        }

        // Wait for all threads to complete
        for (Thread thread : threads) {
            thread.join();
        }
