function closeModalManually() {
    modal.classList.remove('is-visible');

    // This removes the dummy state from the history stack
    // so the next "Back" click actually goes to the previous page.
    if (window.history.state && window.history.state.modalOpen) {
        window.history.back();
    }
}
```

