### Option 2: React (Functional Component)
In React, you want to handle this inside a `useEffect` hook to ensure the listener is cleaned up properly.

```jsx
import React, { useEffect } from 'react';

const Modal = ({ isOpen, onClose }) => {
  useEffect(() => {
    // If the modal is open, push a new state to the history
    if (isOpen) {
      window.history.pushState({ modalOpen: true }, "");
    }

    // Listen for the back button
    const handlePopState = () => {
      // If the modal is currently visible, close it
      if (isOpen) {
        onClose();
      }
    };

    window.addEventListener('popstate', handlePopState);

    // Cleanup listener on unmount
    return () => {
      window.removeEventListener('popstate', handlePopState);
    };
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  return (
    <div className="modal">
      <p>Modal Content</p>
      <button onClick={onClose}>Close</button>
    </div>
  );
};
```

